 if(fellow&&e.selected!==false){ellipse(c,0,-.4,15.7,6.2,null,0,'#dcca83');ellipse(c,0,-.8,13.2,4.8,null,0,'#f6e9b7');const vx=sign*14,vy=frontDepth*5;poly(c,[[vx-2,vy-.3],[vx+2,vy-.3],[vx+sign*2.7,vy+frontDepth*2]],'#f5e6b2',null);}
