 function arm(which,far=false){const swing=(walk?step*which*2.4:0),shoulder=[which*5,-27.5],elbow=[which*6.4,-22+swing],point=p.pose==='point'&&which===(sign<0?-1:1),reading=p.pose==='read';let hand=point?[which*12.8,-26.2]:reading?[which*3.4,-21.4]:[which*5.8,-17.2+swing];if(point)elbow[1]=-24;const armColor=far?shade(coat,-14):shade(coat,5);segment(c,shoulder,elbow,2.05,armColor);segment(c,elbow,[hand[0],hand[1]-.3],1.55,armColor);line(c,[[elbow[0]-.3,elbow[1]],[hand[0]-.3,hand[1]-1.7]],shade(coat,26),.55);ellipse(c,hand[0],hand[1]+.2,1.45,1.8,skin[1],point?.8:0);if(point)line(c,[[hand[0],hand[1]],[hand[0]+which*2.3,hand[1]-.6]],skin[1],.85);}
 arm(sign<0?1:-1,true);
 // A narrow neck, shoulders, coat hem, lapels and worn linen create a small silhouette.
 poly(c,[[-5.8,-28],[-2.7,-30.4],[2.8,-30.3],[5.7,-27.7],[4.5,-20.2],[6,-14.4],[.3,-13.6],[-5.6,-14.8],[-4.8,-21.3]],coat,'#2e2b256f',.65);
 poly(c,[[-5.2,-27.2],[-3,-28.4],[-2.2,-20.3],[-3.4,-14.8],[-5.2,-15.1]],shade(coat,19),null);
 poly(c,[[3.1,-28.9],[5.5,-27.5],[4.4,-20.5],[5.6,-14.7],[1.7,-14.3],[2.1,-22]],shade(coat,-15),null);
