 if(!back){poly(c,[[-2.5,-30],[2.7,-30],[1,-23.4],[-.9,-23.3]],linen,null);poly(c,[[-2.6,-29.3],[-.5,-25.3],[-3,-26]],shade(coat,29),null);poly(c,[[2.5,-29.4],[.5,-25.2],[3.4,-26.4]],shade(coat,15),null);if((index%3===0||fellow)&&!p.casual){poly(c,[[-.5,-28.5],[.6,-28.5],[1.1,-24.4],[.1,-23.5],[-.6,-24.5]],fellow?'#b89a61':'#77513b',null);}for(const yy of[-22.5,-19.1,-15.9])ellipse(c,.4,yy,.55,.55,'#d1bf91');line(c,[[2.5,-20.5],[4.4,-20.8]],shade(coat,-25),.65);}
 else {line(c,[[0,-29],[.4,-20]],shade(coat,-20),.65);line(c,[[-3.9,-23.7],[-1.8,-23]],shade(coat,24),.65);}
 // Side satchel and straps stay visible even while the unit faces away.
