 poly(c,[[hx-2.3,hy-2.8],[hx-.4,hy-3.1],[hx+1.1,hy-2.3],[hx+1.7,hy+.5],[hx+.7,hy+2.5],[hx-1.8,hy+1.6]],skin[1],null);
