function table(c,e,x,y){const p=e.iso(x,y),at=(dx,dy,z=0)=>{const q=e.iso(x+dx,y+dy);return[q.x,q.y+14-z];};ellipse(c,p.x+6,p.y+17,28,6.5,'#2c2b2038');for(const [xx,yy]of[[-.58,-.31],[.58,-.31],[-.58,.31],[.58,.31]]){const top=at(xx,yy,18),foot=at(xx,yy,0);segment(c,top,foot,1.6,'#6c4d2d','#4f3c255c');line(c,[[top[0]-.7,top[1]+3],[foot[0]-.7,foot[1]-2]],'#a18350',.6);}poly(c,[at(-.72,-.43,18),at(.72,-.43,18),at(.72,.43,18),at(-.72,.43,18)],'#a6814e','#634a2c',.8);poly(c,[at(-.72,.43,18),at(.72,.43,18),at(.72,.43,15),at(-.72,.43,15)],'#7d5c35','#5b4228',.5);for(const d of[-.2,0,.2])line(c,[at(-.67,d,18.1),at(.67,d,18.1)],'#c39d61',.5);bookStack(c,e,x-.22,y+.05,19,2);openBook(c,e,x+.27,y-.1,18.5);const cup=at(.48,.23,19);ellipse(c,cup[0],cup[1]-1,2.5,1.2,'#d2c8a6');c.fillStyle='#b7a98b';c.fillRect(cup[0]-2.1,cup[1]-1,4.2,4);ellipse(c,cup[0],cup[1]-1,1.7,.8,'#655b43');}
